import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.1lR7qgqY.js";const u=JSON.parse('{"title":"第 11 章 安全與風險控管","description":"","frontmatter":{},"headers":[],"relativePath":"deploy/11-security.md","filePath":"deploy/11-security.md","lastUpdated":1792998873000}'),o={name:"deploy/11-security.md"};function i(l,t,s,n,h,c){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="第-11-章-安全與風險控管" tabindex="-1">第 11 章 安全與風險控管 <a class="header-anchor" href="#第-11-章-安全與風險控管" aria-label="Permalink to &quot;第 11 章 安全與風險控管&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ● 必要</li><li>狀態: 草稿, 待人工審閱</li><li>資料基準日: 2026-10-26</li><li>待查證: 11.3 的沙箱與機密管理工具版本 (gVisor, Podman, SOPS 等) 為訓練資料內資訊, 可能已過時</li></ul></div><p><strong>結論</strong>: 地端 AI 最有效的安全措施有四項: 不對網際網路開放, 鎖定版本, 縮小權限, 能還原. 這四項成本低, 且能涵蓋 2026 年已知的主要攻擊途徑.</p><h2 id="_11-1-網路暴露與存取控制" tabindex="-1">11.1 網路暴露與存取控制 <a class="header-anchor" href="#_11-1-網路暴露與存取控制" aria-label="Permalink to &quot;11.1 網路暴露與存取控制&quot;">​</a></h2><table tabindex="0"><thead><tr><th>使用情境</th><th>做法</th></tr></thead><tbody><tr><td>單人</td><td>服務只綁 127.0.0.1</td></tr><tr><td>家庭或小團隊</td><td>使用 Tailscale (或 WireGuard), 加上介面本身的帳號系統</td></tr><tr><td>需要 HTTPS 網域</td><td>加 Caddy (自動憑證, 設定最簡單)</td></tr><tr><td>10 人以上, 或已有其他自架服務</td><td>才考慮 Keycloak 或 Authentik 這類 SSO</td></tr></tbody></table><p><strong>不要</strong>用連接埠轉發把服務直接開到網際網路. SentinelOne 與 Censys 曾觀察到 175,108 台暴露的 Ollama 主機 (研究 1); 2026 年 n8n 於 ShadowServer 2026-02-05 的統計中仍有 24,607 台易受攻擊 (SC Media); Langflow 多個漏洞已被實際利用 (見第 13 章). 這幾件事屬於同一類問題.</p><p>上述存取控制工具的版本未於本輪驗證, 屬訓練資料內資訊, 可能已過時; 分級為研究 2 的推論 (信心: 中高).</p><h2 id="_11-2-供應鏈-版本鎖定與映像摘要值" tabindex="-1">11.2 供應鏈: 版本鎖定與映像摘要值 <a class="header-anchor" href="#_11-2-供應鏈-版本鎖定與映像摘要值" aria-label="Permalink to &quot;11.2 供應鏈: 版本鎖定與映像摘要值&quot;">​</a></h2><p>2026-10-21 的 LiteLLM 事件中, v1.107.0, latest, main-latest, main-stable 這些標籤都曾指向惡意映像 (LiteLLM 官方事故報告). 浮動標籤因此不可作為安全依據.</p><p>實務做法:</p><ol><li>容器映像以版本號或摘要值 (digest) 鎖定, 不使用 <code>latest</code>.</li><li>記錄每個元件的安裝版本與日期 (見第 19 章).</li><li>升級前先讀發行說明, 並跑一次 promptfoo 測試集 (第 14 章).</li><li>模型權重優先採用 safetensors 格式, 避免載入來源不明的 pickle 檔 (研究 1 已列為風險).</li><li>發現金鑰外洩時, 依「隔離, 重建, 輪替」處理 (第 20 章).</li></ol><h2 id="_11-3-沙箱與機密管理" tabindex="-1">11.3 沙箱與機密管理 <a class="header-anchor" href="#_11-3-沙箱與機密管理" aria-label="Permalink to &quot;11.3 沙箱與機密管理&quot;">​</a></h2><h3 id="沙箱分級" tabindex="-1">沙箱分級 <a class="header-anchor" href="#沙箱分級" aria-label="Permalink to &quot;沙箱分級&quot;">​</a></h3><p>以下分級為依產業慣例的推論 (信心: 中), gVisor, Firecracker, Podman, Docker rootless 的版本與效能未於本輪驗證.</p><table tabindex="0"><thead><tr><th>層級</th><th>做法</th><th>適用</th></tr></thead><tbody><tr><td>最低</td><td>一般容器 + 非 root 使用者 + <code>--network none</code> + 唯讀根檔案系統 + 記憶體與 CPU 上限</td><td>所有讀者, 成本接近零</td></tr><tr><td>中階</td><td>Podman 或 Docker rootless</td><td>降低容器逃逸後的權限</td></tr><tr><td>進階</td><td>gVisor (runsc) 提供系統呼叫層隔離</td><td>多人環境</td></tr></tbody></table><p>Firecracker 微型虛擬機需要 KVM, 維運成本高, 不建議手冊讀者使用.</p><p><strong>原則</strong>: 只要讓模型執行程式碼, 就必須放進沙箱.</p><h3 id="機密管理" tabindex="-1">機密管理 <a class="header-anchor" href="#機密管理" aria-label="Permalink to &quot;機密管理&quot;">​</a></h3><ul><li><code>.env</code> 檔 (權限 600, 不進版本控制) 足以應付多數讀者.</li><li>Docker Compose secrets 是下一階.</li><li>SOPS 適合用 Git 管理設定的人.</li><li>HashiCorp Vault 或 OpenBao 對手冊讀者過度.</li></ul><p>真正重要的是金鑰外洩後能快速輪替. LiteLLM 兩次事件的官方建議都是「隔離, 重建, 輪替」.</p><h2 id="_11-4-基線檢核表與-owasp-2026-對照" tabindex="-1">11.4 基線檢核表與 OWASP 2026 對照 <a class="header-anchor" href="#_11-4-基線檢核表與-owasp-2026-對照" aria-label="Permalink to &quot;11.4 基線檢核表與 OWASP 2026 對照&quot;">​</a></h2><p>基線檢核表分三組, 隨架構逐層累加, 見<a href="/docs-handbook-poc/deploy/09-architectures">第 9 章</a>.</p><h3 id="owasp-對照" tabindex="-1">OWASP 對照 <a class="header-anchor" href="#owasp-對照" aria-label="Permalink to &quot;OWASP 對照&quot;">​</a></h3><p>OWASP Top 10 for LLM Applications 2026 於 2026 年 8 月初發布 (各來源日期為 8 月 3 日或 8 月 4 日, 尚未能以官方頁面確認). OWASP Top 10 for Agentic Applications 2026 於 2025-12-09 發布, 2026-06-01 更新至 v2.01 (Daxa).</p><table tabindex="0"><thead><tr><th>風險</th><th>本手冊的對應做法</th></tr></thead><tbody><tr><td>LLM03 過度代理 (Excessive Agency), ASI02, ASI03</td><td>工具權限最小化; 寫入與刪除需人工確認</td></tr><tr><td>LLM04 供應鏈, ASI04</td><td>鎖定版本與摘要值; 審核 MCP 伺服器</td></tr><tr><td>ASI05</td><td>程式碼執行放進沙箱</td></tr><tr><td>LLM08 隱藏情境暴露, ASI06</td><td>RAG 資料來源只限可信資料夾</td></tr><tr><td>LLM06 無限制資源消耗</td><td>速率與 token 上限</td></tr></tbody></table><h3 id="護欄模型的定位" tabindex="-1">護欄模型的定位 <a class="header-anchor" href="#護欄模型的定位" aria-label="Permalink to &quot;護欄模型的定位&quot;">​</a></h3><p>分類器護欄不建議作為唯一防線, 理由有兩點:</p><ol><li>字元層級手法可繞過偵測. Hackett 等人 (Mindgard 與 Lancaster University, arXiv 2504.11168) 測試 6 套偵測系統, 「Emoji Smuggling」對提示注入與越獄都達到 100% 攻擊成功率; 該研究未測 Prompt Guard 2.</li><li>Llama Guard 4 (12B) 依參數量推估 BF16 約需 24GB (推論), 超出硬體等級 A 至 D 的能力.</li></ol><p>地端單人環境的主要威脅是被讀進來的文件或網頁中的間接提示注入. 比護欄更有效的做法是縮小工具權限, 要求人工確認, 並把程式碼執行放進沙箱 (信心: 中). 多人對外服務時, 才值得加 Prompt Guard 2 22M 這類輕量分類器, 且僅作為「多一層」. LLM Guard (Protect AI) 儲存庫已於 2026-07-09 封存, 不建議新導入.</p>',29)])])}const b=a(o,[["render",i]]);export{u as __pageData,b as default};
